-- Coast and elevation expressions (ARCHITECTURE.md, "Expression graph" and "Elevation composition").
--
-- For the geography version of each map in config.lua: its coordinate chain, its coast fit and
-- coarse land field (generated by tools/build_geo.py), the lattice detail, the far-field box and its
-- elevation entry, which is also the map's Map type entry. Every term an entry reads is bound to its
-- map and version: the chain carries the map's radii and extent from config.lua and reads the city
-- offset through the version's own per-save names, so a Map type pick alone (it sets only elevation)
-- renders this map, and no map-dependent value reaches the entry through tn_map or a key the maps
-- share. The generated files are name-free data, so a later version's fit and coarse bodies bind the
-- same files to its own chain (config.lua's fits).
--
-- Composition (a version without a term's field leaves its step out):
--   c = fit + detail                       reference pixels; the detail is 0 at pixel centres
--   e = scale * c + if(c > 0, o, -o)       the sign offset: the tile class is the sign of c; a version
--                                          with a shore body (climate-tiles) reads it instead:
--                                          min(gain * c + if(c > 0, o, -o), far) with a land and a
--                                          water gain set for Alien Biomes' beach band and deepwater
--                                          line (config.lua shore)
--   e = min(e, far)                        deep water beyond the map's extent (D15), and from scale 3
--                                          a ring of plain water on its outermost tiles, so deep
--                                          water starts 1 tile beyond it (deepwater borders only
--                                          water in the game); a version with an edge band
--                                          (edge-and-lakes) reads a second coast inside the extent
--                                          instead, a noise-warped band 4 to 20 reference px in
--                                          from the box where land sinks into deep water
--   e = max(e, land)                       the start land guarantee (a version with a spawn record)
--   e = min(e, lake, inland)               the spawn lake and the version's inland lakes (the same);
--                                          a version with a lakes field (edge-and-lakes) reads the
--                                          inland lakes through the per-save switch, inf when off
--   elevation = min(max(e, dams), carves)  a version with waterways: the canals-off dams, then the
--                                          rivers, straits, basins and open canals, each set picked by
--                                          the folded scale (waterways.lua); dams come after the lakes
--                                          so no lake reopens a dammed isthmus, and a carve still cuts
--                                          the start land guarantee
--   elevation = if(e < 0, min(e, stamp), e)  a version with an offshore stamp (resources-enemies): the
--                                          map's stamp key, a Map type fallback, names the stamp body
--                                          (resources.lua) with hotspots on and the neutral zero off,
--                                          so each field's disc is deepwater where the ground is water
--                                          and the coast never moves (APPROVALS 3)
-- No term reads control:water:* or segmentation_multiplier. Vanilla cliffs, moisture and aux do,
-- so every Earth preset also bakes vanilla's three water-slider readers as constants (presets.lua;
-- config.lua's water_slider): the slider moves nothing on a preset world. Every coordinate and
-- constant comes from config.lua (S-5).
local cfg = require("prototypes.config")
local waterways = require("prototypes.expressions.waterways")

-- One require per generated file the release registry lists (the registration scan reads literal
-- module names), keyed by its path as config.lua's release_registry files and fits name it.
local FILES = {
  ["prototypes/generated/geo_europe_v1.lua"] = require("prototypes.generated.geo_europe_v1"),
  ["prototypes/generated/land_coarse_europe_v1.lua"] = require("prototypes.generated.land_coarse_europe_v1"),
  ["prototypes/generated/geo_atlantic_v1.lua"] = require("prototypes.generated.geo_atlantic_v1"),
  ["prototypes/generated/land_coarse_atlantic_v1.lua"] = require("prototypes.generated.land_coarse_atlantic_v1"),
  ["prototypes/generated/geo_olde_world_v1.lua"] = require("prototypes.generated.geo_olde_world_v1"),
  ["prototypes/generated/land_coarse_olde_world_v1.lua"] = require("prototypes.generated.land_coarse_olde_world_v1"),
}

local K = cfg.keys
local C = cfg.coast

local function num(v)
  return string.format(cfg.number_format, v)
end

local E, defined = {}, {}
local function def(name, expression, locals)
  if defined[name] then
    error("two geography versions define " .. name .. ": each version takes names of its own")
  end
  defined[name] = true
  E[#E + 1] = {type = "noise-expression", name = name, expression = expression, local_expressions = locals}
  return E[#E]
end

-- A generated tents body: the fit's name-free locals plus U and V bound to the version's chain. The
-- game parses every body's text at startup (about 0.5 us a byte) and expands every noise-function call
-- there, so each map carries its fit once: one geography version per map until the first release
--.
local function fit_body(name, file, g)
  local fit = FILES[file]
  if not fit then
    error("no generated fit is loaded from " .. tostring(file) .. " for " .. name)
  end
  local L = {}
  for k, v in pairs(fit.locals) do
    L[k] = v
  end
  L.U = g.u
  L.V = g.v
  def(name, fit.expression, L)
end

-- One geography version of a map: its chain, fit bodies, detail, box and elevation entry. Returns
-- the entry's prototype.
local function version(m, g)
  local s = K.scale
  -- the integer-corner offset in tiles, floor(s / corner_offset_divisor) (U2; config.lua)
  local corner = "floor(" .. s .. " / " .. num(cfg.coordinates.corner_offset_divisor) .. ")"

  -- Geo tiles: the map's chosen city sits at world (0, 0) (S7, spawn by shift).
  def(g.gx, "x + " .. g.cx)
  def(g.gy, "y + " .. g.cy)
  -- Reference pixels with pixel centres at integer u, v: the tile holding a pixel centre,
  -- evaluated at its integer corner, reads exactly that centre at every integer scale.
  def(g.u, "(" .. g.gx .. " - " .. corner .. ") / " .. s .. " + " .. num(m.wr))
  def(g.v, "(" .. g.gy .. " - " .. corner .. ") / " .. s .. " + " .. num(m.hr))

  -- The coast fit (Tile only) and the coarse land field, the one land field outside Tile.
  fit_body(g.geo, g.fits.geo, g)
  fit_body(g.land_coarse, g.fits.land_coarse, g)

  -- Lattice detail: each octave's lattice holds every pixel centre (basis noise is 0 there; its
  -- offset is added before the input scale), so T1 at pixel centres sees the fit alone and the
  -- coast moves at most the amplitude between them (S1-cloud; S9).
  local off_x = g.cx .. " - " .. corner .. " + " .. s .. " * " .. num(m.wr)
  local off_y = g.cy .. " - " .. corner .. " + " .. s .. " * " .. num(m.hr)
  local octaves = {}
  for _, o in ipairs(C.detail_octaves) do
    octaves[#octaves + 1] = num(o.weight) .. " * basis_noise{x = x, y = y, seed0 = map_seed, seed1 = " ..
      num(o.seed1) .. ", input_scale = " .. num(o.frequency) .. " / " .. s .. ", offset_x = " .. off_x ..
      ", offset_y = " .. off_y .. "}"
  end
  def(g.detail, num(C.detail_amplitude_px) .. " * clamp(" .. table.concat(octaves, " + ") .. ", " ..
    num(-C.detail_clamp) .. ", " .. num(C.detail_clamp) .. ")")

  -- The far-field box: d is the signed distance in tiles to the edge of the map's extent, the
  -- W s x H s tiles its raster covers (>= 0 inside); beyond it everything is deep water, at any
  -- distance (D15). Tents can reach past the raster edge, so this box, not the fit, ends the map.
  -- The extent's outermost tiles (d = 0) read the edge water from edge_min_scale up, where none of
  -- them holds a pixel centre: ring is 1 there and 0 below, so d < ring never holds at scales 1
  -- and 2.
  local d = "min(" .. g.gx .. " + " .. s .. " * " .. num(m.wr) .. ", " ..
    s .. " * " .. num(m.width_px - m.wr) .. " - 1 - " .. g.gx .. ", " ..
    g.gy .. " + " .. s .. " * " .. num(m.hr) .. ", " ..
    s .. " * " .. num(m.height_px - m.hr) .. " - 1 - " .. g.gy .. ")"
  local ring = "min(1, floor(" .. s .. " / " .. num(C.edge_min_scale) .. "))"
  if g.edge then
    -- The soft map edge (edge-and-lakes; config.lua coast.edge_band): inside the extent a second coast
    -- at the noise-warped band, the version's own transfer of b, its reference px beyond the band's
    -- water edge, so land sinks into deep water where b < 0 and land farther in keeps its elevation
    -- (b at the clamp reads at least any land the coast reads). Every box tile is water, so the ring
    -- is not needed.
    local B = C.edge_band
    local band_octaves = {}
    for _, oc in ipairs(B.octaves) do
      band_octaves[#band_octaves + 1] = num(oc.weight) .. " * basis_noise{x = x, y = y, seed0 = map_seed, seed1 = " ..
        num(oc.seed1) .. ", input_scale = " .. num(1) .. " / (" .. num(oc.wavelength_px) .. " * " .. s ..
        "), offset_x = " .. g.cx .. ", offset_y = " .. g.cy .. "}"
    end
    local locals = {
      d = d,
      warp = num(B.warp_px) .. " * clamp(" .. table.concat(band_octaves, " + ") .. ", -1, 1)",
      b = "clamp(d / " .. s .. " + warp - " .. num(B.width_px) .. ", " .. num(-C.transfer_clamp_px) .. ", " ..
        num(C.transfer_clamp_px) .. ")",
    }
    local o = num(C.transfer_offset)
    local band
    if g.shore then
      local SH = cfg.shore
      locals.gl = "max(" .. num(SH.land.min) .. ", " .. num(SH.land.per_scale) .. " * " .. s .. ")"
      locals.gw = "max(" .. num(SH.water.min) .. ", " .. num(SH.water.per_scale) .. " * " .. s .. ")"
      band = "if(b > 0, gl * b + " .. o .. ", gw * b - " .. o .. ")"
    else
      band = "if(b > 0, " .. s .. " * b + " .. o .. ", " .. s .. " * b - " .. o .. ")"
    end
    def(g.far, "if(d < 0, " .. num(C.far_floor) .. ", " .. band .. ")", locals)
  else
    def(g.far, "if(d < 0, " .. num(C.far_floor) .. ", if(d < ring, " .. num(C.edge_water) .. ", inf))",
      {d = d, ring = ring})
  end

  -- The elevation entry: the sign-offset transfer of the clamped coast field, then the far field.
  -- Never name a local e, pi or inf: the built-in constants win over locals (S9).
  local o = num(C.transfer_offset)
  local cv = "clamp(" .. g.geo .. " + " .. g.detail .. ", " .. num(-C.transfer_clamp_px) .. ", " ..
    num(C.transfer_clamp_px) .. ")"
  local text = "min(if(cv > 0, " .. s .. " * cv + " .. o .. ", " .. s .. " * cv - " .. o .. "), " .. g.far .. ")"
  local locals = {cv = cv}
  -- A version with a shore body (climate-tiles) composes it in place of the transfer: the same sign
  -- offset with the land and water gains recalibrated with Alien Biomes (config.lua shore), so AB's
  -- beach band is a strip a few tiles wide at every scale and the open sea lies below AB's deepwater
  -- line, while the tile class stays the sign of c (T1 unchanged). The body is the version's own: it
  -- reads the version's fit, detail and box.
  if g.shore then
    local SH = cfg.shore
    def(g.shore, "min(if(cv > 0, gl * cv + " .. o .. ", gw * cv - " .. o .. "), " .. g.far .. ")",
      {cv = cv,
       gl = "max(" .. num(SH.land.min) .. ", " .. num(SH.land.per_scale) .. " * " .. s .. ")",
       gw = "max(" .. num(SH.water.min) .. ", " .. num(SH.water.per_scale) .. " * " .. s .. ")"})
    text, locals = g.shore, {}
  end
  -- A version with a spawn record (spawn-cities) adds step 4, the start land guarantee, and step 7,
  -- the spawn lake and the version's inland lakes (spawn.lua defines all three). A version with
  -- waterways (waterways) wraps the rest in steps 5 and 6, the dams and carves (waterways.lua): a
  -- named waterway still cuts the guarantee, and no lake reopens a dammed isthmus.
  local sp = g.spawn
  if sp then
    -- A version with a lakes field (edge-and-lakes) reads its inland lakes through the per-save switch,
    -- a folded if() on the toggle's tn_one or tn_zero: on, the term is the lakes body as before; off,
    -- it folds to inf and the spot noise is never evaluated (U5).
    local lakes = sp.inland_lakes
    if g.lakes then
      locals.lk = "if(" .. g.lakes .. " > " .. num(cfg.hooks.threshold) .. ", " .. sp.inland_lakes .. ", inf)"
      lakes = "lk"
    end
    text = "min(max(" .. text .. ", " .. sp.start_land .. "), " .. sp.spawn_lake .. ", " .. lakes .. ")"
  end
  if g.waterways then
    local ww_locals
    text, ww_locals = waterways.composition(g.waterways, text)
    for k, v in pairs(ww_locals) do
      locals[k] = v
    end
  end
  -- A version with an offshore stamp (resources-enemies) wraps the rest last, through its stamp key; the
  -- local is ev, never e (S9).
  if g.fields then
    locals.ev = text
    text = "if(ev < 0, min(ev, " .. g.fields .. "), ev)"
  end
  return def(g.entry, text, locals)
end

for _, key in ipairs(cfg.map_order) do
  local g = cfg.geography[key]
  local versions = g and g.versions or {}
  for i, v in ipairs(versions) do
    local entry = version(cfg.maps[key], v)
    -- The Map type entry (D2 amended): the newest version of a map's entry carries these GUI fields,
    -- which tests/frozen.json never hashes.
    if i == #versions then
      entry.intended_property = K.elevation
      entry.localised_name = {"noise-expression." .. v.entry}
      entry.order = g.map_type_order
    end
  end
end

data:extend(E)
